/**
 * Identify which wallet brand actually answers behind an injected provider.
 *
 * Connector names lie: with Rabby (or Phantom, Brave, …) set as the default
 * wallet, the "MetaMask" connector binds to Rabby's provider — Rabby sets
 * `isMetaMask` for compatibility. So specific-brand flags are checked before
 * the generic `isMetaMask`.
 */
export function detectEvmProviderBrand(provider: unknown): string | undefined {
  if (!provider || typeof provider !== "object") return undefined;
  const flags = provider as InjectedProvider;
  if (flags.isRabby) return "Rabby";
  if (flags.isPhantom) return "Phantom";
  if (flags.isBraveWallet) return "Brave Wallet";
  if (flags.isRainbow) return "Rainbow";
  if (flags.isCoinbaseWallet) return "Coinbase Wallet";
  if (flags.isMetaMask) return "MetaMask";
  return undefined;
}

export type EvmConnectionBrandInput = {
  connectorId: string;
  address: string;
};

/**
 * Resolve the real brand for each live EVM connection by sniffing the
 * underlying provider. Returns `connectorId → brand label`; connections whose
 * provider exposes no brand flags (Para embedded, WalletConnect, …) are
 * absent — callers fall back to the connector name.
 *
 * Re-sniffs whenever the connection set changes, so flipping the wallet's
 * "default wallet" setting is picked up without a page refresh.
 */
export function useEvmProviderBrands(
  connections: readonly EvmConnectionBrandInput[],
  connectors: readonly Connector[],
): Record<string, string> {
  const [brands, setBrands] = useState<Record<string, string>>({});
  // Re-sniff on membership changes without retriggering on unrelated renders.
  const membershipKey = useMemo(
    () =>
      connections
        .map((connection) => `${connection.connectorId}:${connection.address}`)
        .sort()
        .join("|"),
    [connections],
  );
  const connectionsRef = useRef(connections);
  connectionsRef.current = connections;
  const connectorsRef = useRef(connectors);
  connectorsRef.current = connectors;

  useEffect(() => {
    if (!membershipKey) {
      setBrands((previous) => (Object.keys(previous).length ? {} : previous));
      return;
    }

    let cancelled = false;
    void Promise.all(
      connectionsRef.current.map(async (connection) => {
        const connector = connectorsRef.current.find(
          (candidate) => candidate.uid === connection.connectorId,
        );
        if (!connector?.getProvider) return null;
        try {
          const provider = await connector.getProvider();
          const brand = detectEvmProviderBrand(provider);
          return brand ? ([connection.connectorId, brand] as const) : null;
        } catch {
          return null;
        }
      }),
    ).then((entries) => {
      if (cancelled) return;
      setBrands(
        Object.fromEntries(
          entries.filter(
            (entry): entry is readonly [string, string] => entry !== null,
          ),
        ),
      );
    });

    return () => {
      cancelled = true;
    };
  }, [membershipKey]);

  return brands;
}

export type GracefulEvmIdentity = {
  address?: string;
  chainId?: number;
  connectorId?: string;
  walletName?: string;
};

export type GracefulEvmIdentityResult = {
  identity: GracefulEvmIdentity;
  disconnectedAt: number | null;
  usingCachedIdentity: boolean;
};

export function resolveGracefulEvmIdentity({
  current,
  previous,
  selectedChainId,
  disconnectedAt,
  now,
  graceMs,
  explicitDisconnect,
}: {
  current: GracefulEvmIdentity;
  previous: GracefulEvmIdentity | null;
  selectedChainId?: number;
  disconnectedAt: number | null;
  now: number;
  graceMs: number;
  explicitDisconnect: boolean;
}): GracefulEvmIdentityResult {
  if (current.address) {
    return {
      identity: current,
      disconnectedAt: null,
      usingCachedIdentity: false,
    };
  }

  if (!previous?.address || explicitDisconnect) {
    return {
      identity: current,
      disconnectedAt: null,
      usingCachedIdentity: false,
    };
  }

  const startedAt = disconnectedAt ?? now;
  if (now - startedAt > graceMs) {
    // Keep the original disconnect timestamp: resetting it to null here
    // would let the very next render restart the grace window (previous is
    // still cached), making the identity oscillate cached → empty → cached
    // for as long as the wallet stays disconnected. Only a live reconnect
    // (the `current.address` branch above) clears the timestamp.
    return {
      identity: current,
      disconnectedAt: startedAt,
      usingCachedIdentity: false,
    };
  }

  return {
    identity: {
      ...previous,
      chainId: selectedChainId ?? current.chainId ?? previous.chainId,
    },
    disconnectedAt: startedAt,
    usingCachedIdentity: true,
  };
}

"use client";

import type {
  SvmCluster,
  SvmNetworkConfigInput,
  SvmNetworkOption,
} from "../../types";

export const DEFAULT_SVM_CLUSTER: SvmCluster = "solana:mainnet";

export const DEFAULT_SVM_RPC_HTTP_URLS: Record<SvmCluster, string> = {
  "solana:mainnet": "https://api.mainnet-beta.solana.com",
  "solana:devnet": "https://api.devnet.solana.com",
  "solana:testnet": "https://api.testnet.solana.com",
};

export function getDefaultSvmNetworkLabel(cluster: SvmCluster): string {
  switch (cluster) {
    case "solana:mainnet":
      return "Solana Mainnet";
    case "solana:testnet":
      return "Solana Testnet";
    case "solana:devnet":
    default:
      return "Solana Devnet";
  }
}

function buildLegacySvmNetwork(
  config?: SvmNetworkConfigInput,
): SvmNetworkOption {
  const cluster = config?.cluster ?? DEFAULT_SVM_CLUSTER;
  return {
    id: cluster,
    label: getDefaultSvmNetworkLabel(cluster),
    cluster,
    rpcHttpUrl: config?.rpcHttpUrl ?? DEFAULT_SVM_RPC_HTTP_URLS[cluster],
    rpcWsUrl: config?.rpcWsUrl,
    isDefault: true,
  };
}

export function normalizeSvmNetworkOptions(
  config?: SvmNetworkConfigInput,
): readonly SvmNetworkOption[] {
  const rawNetworks = config?.networks;
  if (!rawNetworks || rawNetworks.length === 0) {
    return [buildLegacySvmNetwork(config)];
  }

  return rawNetworks.map((network, index) => ({
    id: network.id,
    label: network.label || getDefaultSvmNetworkLabel(network.cluster),
    cluster: network.cluster,
    rpcHttpUrl:
      network.rpcHttpUrl ?? DEFAULT_SVM_RPC_HTTP_URLS[network.cluster],
    rpcWsUrl: network.rpcWsUrl,
    isDefault:
      network.isDefault ??
      (index === 0 && !rawNetworks.some((item) => item.isDefault)),
  }));
}

export function resolveSelectedSvmNetwork(
  networks: readonly SvmNetworkOption[],
  selectedNetworkId?: string,
): SvmNetworkOption {
  return (
    networks.find((network) => network.id === selectedNetworkId) ??
    networks.find((network) => network.isDefault) ??
    networks[0]
  );
}

