export class WalletRegistryStore {
  private state: WalletRegistryState;
  private readonly subscribers = new Set<() => void>();
  private readonly executors: CommandExecutors;
  private readonly storageKey: string;
  private settleTimer: number | null = null;

  constructor(opts: {
    executors: CommandExecutors;
    storageKey: string;
    initialNow: number;
  }) {
    this.executors = opts.executors;
    this.storageKey = opts.storageKey;
    this.state = reduce(createInitialState(), {
      type: "boot/init",
      persisted: loadPersisted(opts.storageKey, { migrateDestructively: true }),
      now: opts.initialNow,
    });
  }

  getSnapshot(): WalletRegistryState {
    return this.state;
  }

  subscribe(cb: () => void): () => void {
    this.subscribers.add(cb);
    return () => {
      this.subscribers.delete(cb);
    };
  }

  dispatch(event: RegistryEvent): void {
    const prev = this.state;
    const next = reduce(prev, event);
    if (next === prev) return;

    this.state = next;
    for (const subscriber of this.subscribers) subscriber();

    const commands = planCommands(prev, next, event);
    for (const command of commands) {
      this.executeCommand(command);
    }

    if (event.type.startsWith("wagmi/") && event.type !== "wagmi/settled") {
      this.scheduleSettledPass(SETTLE_QUIET_MS);
    }
  }

  dispose(): void {
    if (this.settleTimer !== null && typeof window !== "undefined") {
      window.clearTimeout(this.settleTimer);
    }
    this.settleTimer = null;
  }

  private executeCommand(command: RegistryCommand): void {
    switch (command.kind) {
      case "persist":
        savePersisted(this.state, this.storageKey);
        break;
      case "debug":
        walletDebug(command.event, command.data);
        break;
      case "wagmi/reconnect":
        this.runAsync(command.kind, async () => {
          try {
            await this.executors.wagmiReconnect(command.stableIds);
          } finally {
            this.scheduleSettledPass(this.reconnectSettleDelayMs());
          }
        });
        break;
      case "wagmi/connect":
        this.runAsync(command.kind, () =>
          this.executors.wagmiConnect(command.stableId),
        );
        break;
      case "wagmi/disconnect":
        this.runAsync(command.kind, () =>
          this.executors.wagmiDisconnect(command.uid),
        );
        break;
      case "provider/logout":
        this.runAsync(command.kind, () => this.executors.providerLogout());
        break;
      default:
        break;
    }
  }

  private runAsync(
    kind: RegistryCommand["kind"],
    fn: () => Promise<void>,
  ): void {
    void fn().catch((error: unknown) => {
      walletDebug("registry:command-error", {
        kind,
        error: error instanceof Error ? error.message : String(error),
      });
    });
  }

  private reconnectSettleDelayMs(): number {
    const authFlowSuppressed =
      this.state.heal.suppressedUntil !== null &&
      Date.now() < this.state.heal.suppressedUntil &&
      (this.state.heal.suppressionReason === "para-social-login" ||
        this.state.heal.suppressionReason === "para-auth-modal" ||
        this.state.heal.suppressionReason === "para-evm-connect-fallback" ||
        this.state.heal.suppressionReason === "para-account-modal");
    return authFlowSuppressed ? AUTH_FLOW_RECONNECT_SETTLE_MS : SETTLE_QUIET_MS;
  }

  private scheduleSettledPass(delayMs: number): void {
    const run = () => {
      this.settleTimer = null;
      this.dispatch({ type: "wagmi/settled", now: Date.now() });
    };
    if (typeof window === "undefined") {
      queueMicrotask(run);
      return;
    }
    if (this.settleTimer !== null) {
      window.clearTimeout(this.settleTimer);
    }
    this.settleTimer = window.setTimeout(run, delayMs);
  }
}

import { buildAccounts } from "../accounts";
import type { AomiAccount, WalletFamily } from "../types";
import { resolveGracefulEvmIdentity } from "../runtime/evm/identity-grace";
import { EVM_IDENTITY_GRACE_MS } from "./types";
import type {
  ActiveRef,
  RegistryConnection,
  WalletRegistryState,
} from "./types";

export function selectActiveEvm(
  state: WalletRegistryState,
): ActiveRef | undefined {
  return state.activeByFamily.evm;
}

export function selectSolana(
  state: WalletRegistryState,
): RegistryConnection | undefined {
  const active = state.activeByFamily.solana;
  if (active) {
    return state.connections.find(
      (connection) =>
        connection.family === "solana" &&
        connection.address === active.address &&
        (!active.uid || connection.uid === active.uid),
    );
  }
  return state.connections.find((connection) => connection.family === "solana");
}

function findActiveConnection(
  state: WalletRegistryState,
  family: WalletFamily,
): RegistryConnection | undefined {
  const active = state.activeByFamily[family];
  if (!active) return undefined;
  return state.connections.find((connection) => {
    if (connection.family !== family) return false;
    if (active.uid && connection.uid === active.uid) return true;
    if (active.stableId && connection.stableId !== active.stableId) {
      return false;
    }
    const left =
      family === "evm" ? connection.address.toLowerCase() : connection.address;
    const right =
      family === "evm" ? active.address.toLowerCase() : active.address;
    return left === right;
  });
}

export function selectEvmIdentity(
  state: WalletRegistryState,
  now: number,
  selectedChainId?: number,
): {
  address?: string;
  chainId?: number;
  connectorId?: string;
  walletName?: string;
} {
  const activeConnection = findActiveConnection(state, "evm");
  const current = activeConnection
    ? {
        address: activeConnection.address,
        chainId: activeConnection.chainId,
        connectorId: activeConnection.uid,
        walletName: activeConnection.walletName,
      }
    : {};
  const explicitDisconnect = Boolean(
    state.evmGrace.last?.address &&
    state.intents.droppedAddresses.includes(
      state.evmGrace.last.address.toLowerCase(),
    ),
  );

  return resolveGracefulEvmIdentity({
    current,
    previous: state.evmGrace.last,
    selectedChainId,
    disconnectedAt: state.evmGrace.disconnectedAt,
    now,
    graceMs: EVM_IDENTITY_GRACE_MS,
    explicitDisconnect,
  }).identity;
}

export function selectAccounts(
  state: WalletRegistryState,
  now: number,
  selectedChainId?: number,
): AomiAccount[] {
  const activeEvm = state.activeByFamily.evm;
  const evmIdentity = selectEvmIdentity(state, now, selectedChainId);
  const evmConnections = state.connections
    .filter((connection) => connection.family === "evm")
    .map((connection) => ({
      id: connection.uid,
      walletName: connection.walletName ?? connection.stableId,
      address: connection.address,
      chainId: connection.chainId,
    }));

  if (evmIdentity.address && evmConnections.length === 0) {
    evmConnections.push({
      id: evmIdentity.connectorId ?? "cached-evm",
      walletName: evmIdentity.walletName ?? "Wallet",
      address: evmIdentity.address,
      chainId: evmIdentity.chainId,
    });
  }

  const solana = selectSolana(state);
  return buildAccounts({
    evmConnections,
    activeEvmAddress: evmIdentity.address,
    activeEvmConnectionId: activeEvm?.uid ?? evmIdentity.connectorId,
    solanaConnections: solana
      ? [
          {
            id: solana.uid,
            publicKey: solana.address,
            walletName: solana.walletName,
          },
        ]
      : [],
    activeSolanaAddress: solana?.address,
  });
}

